function requestOperation<Identifier extends keyof OperationInputs>(
  baseAddress: string,
  specification: OperationSpecification,
  input: OperationInputs[Identifier],
  signal?: AbortSignal,
): Effect.Effect<
  OperationResponses[Identifier],
  TransportFailure | ProtocolFailure | DeclaredFailure
>;
function requestOperation(
  baseAddress: string,
  specification: OperationSpecification,
  input: OperationInputs[keyof OperationInputs],
  signal?: AbortSignal,
): Effect.Effect<unknown, TransportFailure | ProtocolFailure | DeclaredFailure> {
  return Effect.tryPromise({
    catch: (cause) =>
      cause instanceof TransportFailure ||
      cause instanceof ProtocolFailure ||
      cause instanceof DeclaredFailure
        ? cause
        : TransportFailure.make({
            message: cause instanceof Error ? cause.message : "Connection failed",
          }),
    try: async () => {
      let path = specification.path;
      if ("path" in input && input.path !== undefined) {
        for (const [name, value] of Object.entries(input.path)) {
          path = path.replace(`{${name}}`, encodeURIComponent(String(value)));
        }
      }
      const requestUrl = new URL(
        `${baseAddress}${path}`,
        baseAddress || globalThis.location?.origin || "http://localhost",
      );
      if ("query" in input && input.query !== undefined) {
        for (const [name, value] of Object.entries(input.query)) {
          if (value !== undefined) requestUrl.searchParams.set(name, String(value));
        }
      }
      const headers = new Headers("headers" in input ? input.headers : undefined);
      let body: BodyInit | undefined;
      if ("body" in input && input.body !== undefined) {
        if (input.body instanceof FormData) body = input.body;
        else {
          headers.set("content-type", specification.requestMediaType ?? "application/json");
          body = JSON.stringify(input.body);
        }
      }
      let response: Response;
      try {
        response = await fetch(requestUrl, { body, headers, method: specification.method, signal });
      } catch (cause) {
        throw TransportFailure.make({
          message: cause instanceof Error ? cause.message : "Connection failed",
        });
      }
      const mediaType = response.headers.get("content-type") ?? "";
      const successResponse = specification.successResponses.find(
        ({ status }) => status === response.status,
      );
      if (successResponse === undefined) {
        if (mediaType.includes("application/json")) {
          const failure: unknown = await response.json();
          if (
            failure !== null &&
            typeof failure === "object" &&
            "code" in failure &&
            "message" in failure
          ) {
            throw DeclaredFailure.make({
              code: String(failure.code),
              details: "details" in failure ? failure.details : undefined,
              message: String(failure.message),
              status: response.status,
            });
          }
        }
        throw ProtocolFailure.make({
          message: `Unexpected response status ${response.status}`,
          status: response.status,
        });
      }
      if (response.status === 204 || specification.method === "HEAD") return undefined;
      if (successResponse.responseMediaType === "application/octet-stream")
        return new Uint8Array(await response.arrayBuffer());
      if (!mediaType.includes("application/json"))
        throw ProtocolFailure.make({
          message: "Expected application/json response",
          status: response.status,
        });
      try {
        return await response.json();
      } catch {
        throw ProtocolFailure.make({ message: "Malformed JSON response", status: response.status });
      }
    },
  });
}

